import React from "react";
import {
  AbsoluteFill,
  Easing,
  OffthreadVideo,
  interpolate,
  staticFile,
  useCurrentFrame,
} from "remotion";
import { loadFont as loadSans } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadSerif } from "@remotion/google-fonts/PlayfairDisplay";
import OFFSET from "./offset.json";

// ANA ULTRAOFOCUS — "13 ou 22 unidades no frontal?" (trend dos harmonizadores, 16/10).
// O vídeo dela (selfie, 70 s) ocupa o quadro; um painel creme embaixo cobre o pijama e traz o lettering e os
// ícones de toxina. O vídeo sobe (offset.json, 5 pontos por segundo) para o queixo nunca ficar atrás do painel.
// Tempos = palavra na fala original (sem cortes).

const sans = loadSans("normal", { weights: ["500", "700", "800"], subsets: ["latin"] }).fontFamily;
const serif = loadSerif("italic", { weights: ["600"], subsets: ["latin"] }).fontFamily;

export const ANA_FPS = 30;
export const ANA_FRAMES = Math.round(70.4 * ANA_FPS);

const CREAM = "#FBF6F1";
const INK = "#2A1F2D";
const GOLD = "#B8875A";
const BERRY = "#A8325E";
const MUTED = "#8A7B82";
const PANEL_TOP = 1450;
const END = 67.0; // entra o cartão final

const ez = Easing.bezier(0.2, 0.9, 0.25, 1);
const cl = (v: number) => Math.min(1, Math.max(0, v));
const p = (t: number, a: number, d = 0.4) => ez(cl((t - a) / d));

// ---------- peças ----------
const Kicker: React.FC<{ t: number; a: number; children: React.ReactNode }> = ({ t, a, children }) => {
  const e = p(t, a, 0.35);
  return (
    <div
      style={{
        fontFamily: sans,
        fontWeight: 700,
        fontSize: 32,
        letterSpacing: 6,
        color: GOLD,
        textTransform: "uppercase",
        opacity: e,
        transform: `translateY(${(1 - e) * 18}px)`,
        textAlign: "center",
      }}
    >
      {children}
    </div>
  );
};

// texto principal: entra subindo de uma máscara e fica parado
const Big: React.FC<{ t: number; a: number; size?: number; children: React.ReactNode; color?: string }> = ({
  t,
  a,
  size = 92,
  children,
  color = INK,
}) => {
  const e = p(t, a, 0.45);
  return (
    <div style={{ overflow: "hidden", padding: "6px 0" }}>
      <div
        style={{
          fontFamily: sans,
          fontWeight: 800,
          fontSize: size,
          lineHeight: 1.04,
          color,
          textAlign: "center",
          letterSpacing: -1.5,
          transform: `translateY(${(1 - e) * 110}%)`,
        }}
      >
        {children}
      </div>
    </div>
  );
};

const Em: React.FC<{ children: React.ReactNode; color?: string }> = ({ children, color = BERRY }) => (
  <span style={{ fontFamily: serif, fontStyle: "italic", fontWeight: 600, color, letterSpacing: 0 }}>{children}</span>
);

const Syringe: React.FC<{ size: number; fill?: number }> = ({ size, fill = 1 }) => (
  <svg width={size} height={size * 0.3} viewBox="0 0 200 60">
    <rect x="4" y="22" width="10" height="16" rx="3" fill={GOLD} />
    <rect x="14" y="27" width="34" height="6" fill={GOLD} />
    <rect x="48" y="14" width="6" height="32" rx="2" fill={INK} />
    <rect x="54" y="18" width="96" height="24" rx="6" fill="none" stroke={INK} strokeWidth="4" />
    <rect x="58" y="22" width={88 * fill} height="16" rx="3" fill={BERRY} opacity="0.85" />
    {[70, 86, 102, 118, 134].map((x) => (
      <rect key={x} x={x} y="18" width="2.5" height="9" fill={INK} />
    ))}
    <rect x="150" y="25" width="16" height="10" rx="2" fill={INK} />
    <rect x="166" y="28.5" width="30" height="3" fill={MUTED} />
  </svg>
);

const Vial: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size * 0.5} height={size} viewBox="0 0 50 100">
    <rect x="12" y="2" width="26" height="14" rx="3" fill={GOLD} />
    <rect x="16" y="16" width="18" height="8" fill={INK} />
    <rect x="6" y="24" width="38" height="72" rx="8" fill="none" stroke={INK} strokeWidth="4" />
    <rect x="10" y="50" width="30" height="42" rx="5" fill={BERRY} opacity="0.85" />
    <rect x="10" y="60" width="30" height="16" fill={CREAM} opacity="0.9" />
  </svg>
);

// rosto em linha com os pontos de aplicação (frontal ou glabela)
const FaceIcon: React.FC<{ t: number; a: number; zone: "frontal" | "glabela"; size: number }> = ({ t, a, zone, size }) => {
  const pts =
    zone === "frontal"
      ? [
          [70, 52],
          [100, 46],
          [130, 52],
          [82, 68],
          [118, 68],
        ]
      : [
          [100, 98],
          [86, 92],
          [114, 92],
        ];
  return (
    <svg width={size} height={size} viewBox="0 0 200 200">
      <path
        d="M100 20 C 150 20 168 62 166 104 C 164 150 132 184 100 184 C 68 184 36 150 34 104 C 32 62 50 20 100 20 Z"
        fill="none"
        stroke={INK}
        strokeWidth="5"
      />
      <path d="M66 96 Q 80 88 92 96" fill="none" stroke={INK} strokeWidth="4" strokeLinecap="round" />
      <path d="M108 96 Q 120 88 134 96" fill="none" stroke={INK} strokeWidth="4" strokeLinecap="round" />
      <path d="M100 104 L 94 132 L 104 134" fill="none" stroke={INK} strokeWidth="4" strokeLinecap="round" />
      <path d="M84 152 Q 100 160 116 152" fill="none" stroke={INK} strokeWidth="4" strokeLinecap="round" />
      {pts.map(([x, y], i) => {
        const e = p(t, a + 0.25 + i * 0.12, 0.3);
        return <circle key={i} cx={x} cy={y} r={7 * e} fill={BERRY} opacity={e} />;
      })}
    </svg>
  );
};

// número dentro de um círculo; "state" decide destaque ou riscado
const Num: React.FC<{ n: string; t: number; a: number; hi?: number; cut?: number; size?: number }> = ({
  n,
  t,
  a,
  hi,
  cut,
  size = 210,
}) => {
  const e = p(t, a, 0.4);
  const h = hi === undefined ? 0 : p(t, hi, 0.3);
  const c = cut === undefined ? 0 : p(t, cut, 0.35);
  const punch = hi === undefined ? 1 : 1 + 0.12 * Math.sin(Math.PI * cl((t - hi) / 0.35));
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: size,
        border: `6px solid ${h > 0 ? BERRY : INK}`,
        background: `rgba(168,50,94,${h})`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        position: "relative",
        transform: `scale(${(0.6 + 0.4 * e) * punch})`,
        opacity: e * (1 - 0.55 * c),
      }}
    >
      <span
        style={{
          fontFamily: sans,
          fontWeight: 800,
          fontSize: size * 0.52,
          color: h > 0.5 ? CREAM : INK,
          letterSpacing: -3,
        }}
      >
        {n}
      </span>
      {c > 0 && (
        <div
          style={{
            position: "absolute",
            left: "8%",
            top: "48%",
            width: `${84 * c}%`,
            height: 10,
            background: BERRY,
            borderRadius: 6,
            transform: "rotate(-28deg)",
            transformOrigin: "left center",
          }}
        />
      )}
    </div>
  );
};

const Check: React.FC<{ t: number; a: number; size?: number }> = ({ t, a, size = 70 }) => {
  const e = p(t, a, 0.4);
  return (
    <svg width={size} height={size} viewBox="0 0 70 70" style={{ opacity: e, transform: `scale(${0.5 + 0.5 * e})` }}>
      <circle cx="35" cy="35" r="33" fill={BERRY} />
      <path
        d="M20 36 L31 47 L51 25"
        fill="none"
        stroke={CREAM}
        strokeWidth="7"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray="50"
        strokeDashoffset={50 * (1 - p(t, a + 0.15, 0.35))}
      />
    </svg>
  );
};

// ---------- cenas do painel ----------
type Scene = { a: number; b: number; r: (t: number, a: number) => React.ReactNode };

const Col: React.FC<{ children: React.ReactNode; gap?: number }> = ({ children, gap = 22 }) => (
  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
const Row: React.FC<{ children: React.ReactNode; gap?: number }> = ({ children, gap = 40 }) => (
  <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap }}>{children}</div>
