const Chip: React.FC<{ t: number; a: number; children: React.ReactNode }> = ({ t, a, children }) => {
  const e = p(t, a, 0.35);
  return (
    <div
      style={{
        fontFamily: sans,
        fontWeight: 800,
        fontSize: 50,
        color: CREAM,
        background: e > 0 ? INK : "transparent",
        padding: "18px 30px",
        borderRadius: 60,
        opacity: e,
        transform: `translateY(${(1 - e) * 40}px) scale(${0.8 + 0.2 * e})`,
      }}
    >
      {children}
    </div>
