// ---------- vídeo ----------
const offsetAt = (t: number) => {
  const ys = OFFSET.y as number[];
  const i = t / OFFSET.step;
  const i0 = Math.min(ys.length - 1, Math.max(0, Math.floor(i)));
  const i1 = Math.min(ys.length - 1, i0 + 1);
  return ys[i0] + (ys[i1] - ys[i0]) * (i - i0);
};

// pequenos empurrões de câmera nos momentos fortes
const PUNCH = [2.7, 20.6, 31.3, 35.15, 53.55, 65.8];

const Footage: React.FC<{ t: number }> = ({ t }) => {
  let s = 1.03 + 0.012 * Math.sin(t * 0.35);
  for (const a of PUNCH) {
    const d = t - a;
    if (d >= 0 && d < 1.2) s += 0.05 * Math.exp(-d * 4) * Math.min(1, d * 12 + (a === 0 ? 1 : 0));
  }
  const intro = 0; // v2: sem zoom de entrada, abre direto
  const endBlur = interpolate(t, [END - 0.1, END + 0.5], [0, 34], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const endDark = interpolate(t, [END - 0.1, END + 0.5], [0, 0.35], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <AbsoluteFill style={{ backgroundColor: INK }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: 1080,
          height: 1936,
          transform: `translateY(${-offsetAt(t)}px) scale(${s + intro * 0.1})`,
          transformOrigin: "50% 38%",
          filter: endBlur > 0 ? `blur(${endBlur}px)` : undefined,
        }}
      >
        <OffthreadVideo src={staticFile("ana/video-hd.mp4")} muted style={{ width: 1080, height: 1936 }} />
      </div>
      <AbsoluteFill style={{ backgroundColor: `rgba(42,31,45,${endDark})` }} />
    </AbsoluteFill>
  );
};

// ---------- painel ----------
const Panel: React.FC<{ t: number }> = ({ t }) => {
  const grow = p(t, END, 0.55);
  const top = PANEL_TOP - grow * 1030;
  const scene = SCENES.find((s) => t >= s.a && t < s.b);
  let body: React.ReactNode = null;
  let op = 1;
  if (scene) {
    body = scene.r(t, scene.a);
    op = interpolate(t, [scene.b - 0.16, scene.b], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  }
  return (
    <>
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: top - 90,
          height: 90,
          background: "linear-gradient(to bottom, rgba(42,31,45,0), rgba(42,31,45,0.22))",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top,
          bottom: -2,
          backgroundColor: CREAM,
          borderTopLeftRadius: 56,
          borderTopRightRadius: 56,
          boxShadow: "0 -12px 40px rgba(42,31,45,0.25)",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: 22,
            width: 120,
            height: 6,
            borderRadius: 4,
            backgroundColor: GOLD,
            opacity: 0.7,
            transform: "translateX(-50%)",
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 120,
            right: 120,
            top: 30,
            height: 1920 - PANEL_TOP - 30,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            opacity: op,
          }}
        >
          {body}
        </div>
      </div>
    </>
  );
};

// ---------- cartão final ----------
const EndCard: React.FC<{ t: number }> = ({ t }) => {
  if (t < END + 0.2) return null;
  const a = END + 0.35;
  const float = Math.sin((t - a) * 1.6) * 8;
  return (
    <div
      style={{
        position: "absolute",
        left: 120,
        right: 120,
        top: PANEL_TOP - 1030 + 40,
        height: 1920 - (PANEL_TOP - 1030) - 40,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 40,
      }}
    >
      <div style={{ display: "flex", alignItems: "flex-end", gap: 36, opacity: p(t, a, 0.4) }}>
        <div style={{ transform: `translateY(${float}px) rotate(-14deg)` }}>
          <Syringe size={380} fill={1} />
        </div>
        <div style={{ transform: `translateY(${-float}px)` }}>
          <Vial size={220} />
        </div>
      </div>
      <Num n="22" t={t} a={a + 0.15} hi={a + 0.35} size={360} />
      <Big t={t} a={a + 0.5} size={104}>
        unidades no <Em>frontal</Em>
      </Big>
      <div style={{ height: 6 }} />
      <Kicker t={t} a={a + 1.1}>E você?</Kicker>
      <Big t={t} a={a + 1.25} size={84}>
        Comenta: <Em>13 ou 22?</Em>
      </Big>
    </div>
  );
};

export const Ana: React.FC = () => {
  const t = useCurrentFrame() / ANA_FPS;
  return (
    <AbsoluteFill style={{ backgroundColor: INK }}>
      <Footage t={t} />
      <Panel t={t} />
      <EndCard t={t} />
    </AbsoluteFill>
  );
};

import React from "react";
